import {rppStatistics} from './planning-rpp-statistics-data.js';
export const rppStatisticsDefinitions={rppCountsStudy:{title:'Explore a dated pension-table snapshot',fields:[['rppEndYear','Last table reference year displayed (1 January)',2025,2022,2025,1]]}};
export function rppCountsResult(kind,input){
 if(kind!=='rppCountsStudy')throw Error('Unknown pension-statistics view');
 const rows=rppStatistics.rows.filter(r=>r.referenceYear<=input.rppEndYear),base=rows[0],last=rows.at(-1);
 const shared={unit:'integer',tableUnit:'Count in units',source:rppStatistics.url,sourceLabel:'Statistics Canada · Table 11-10-0099-01'};
 return {metrics:[['Plans at the selected reference date',last.plans,'integer'],['Active members reported for that reference year',last.members,'integer'],['Change in reported members from 2021 reference',last.members/base.members-1,'percent']],note:'Fixed public snapshot released 28 July 2026 and reviewed 25 October 2026. The control filters table reference years; it does not fetch new data or choose a forecast. Plan counts refer to 1 January. Membership counts relate to plan year-ends in the preceding calendar year, normally 31 December. These are distinct reporting clocks. Selected dimensions: Canada, total registered pension plans, count statistics in units. No household balance, pension-income quotation, worker-coverage denominator or personal entitlement is calculated.',charts:[
  {...shared,id:'rpp-count-indices',type:'line',yMin:95,yMax:115,title:'Compare changes after giving each series its own 2021 baseline',unit:'decimal',unitLabel:'Index; 2021 reference = 100; vertical axis 95–115',tableUnit:'Index; 2021 reference = 100',evidence:'Derived from official statistics',xMin:2021,xLabel:'Table reference year (1 January)',series:[{name:'Number of plans, indexed',rows:rows.map(r=>({x:r.referenceYear,value:r.plans/base.plans*100}))},{name:'Active members, indexed',dash:true,rows:rows.map(r=>({x:r.referenceYear,value:r.members/base.members*100}))}],note:'The focused vertical axis spans 95–115. Each series is divided by its own 2021 reference value and multiplied by 100. An index of 110 means 10% above that series’s baseline; it is not 110% of workers. The reference-year alignment does not turn prior-plan-year membership into a same-day observation.'},
  {...shared,id:'rpp-plan-counts',type:'bar',title:'Read the absolute number of plans separately',unitLabel:'Number of registered pension plans',rows:rows.map(r=>({label:'1 January '+r.referenceYear,value:r.plans})),note:'The value axis starts at zero. These are plans, not members or dollars. A change in plan counts alone does not identify the cause, establish a change in an individual’s benefits or measure participation as a share of employed people.'},
  {...shared,id:'rpp-member-counts',type:'line',title:'Read reported active membership on its own count scale',unitLabel:'Active members reported for each table reference year',xMin:2021,xLabel:'Table reference year',series:[{name:'Reported active members',rows:rows.map(r=>({x:r.referenceYear,value:r.members}))}],note:'The publisher places these membership counts under January reference years but measures membership at plan year-ends in the preceding calendar year. The last reference is not a live count as of today. No employed-population denominator or deduplicated-worker coverage rate is inferred.'},
  {...shared,id:'rpp-funding-members',type:'bar',axisTicks:2,title:'Membership by funding instrument at the selected table reference',unitLabel:'Reported active members · reference year '+last.referenceYear,rows:[...last.funding].sort((a,b)=>b.members-a.members).map(r=>({label:r.label,value:r.members})),note:'The six top-level funding categories reconcile to the selected total. Insurance-contract subcategories are excluded here to avoid counting the same members in both a parent and its children. Funding instrument is a legal/contractual classification, distinct from defined-benefit versus defined-contribution design or an investment asset allocation.'}
 ]};
}
